import{_ as t,o as s,c as i,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"TUI engine: the full-screen desktop and its pages","description":"","frontmatter":{},"headers":[],"relativePath":"arch/tui-engine.md","filePath":"arch/tui-engine.md"}'),n={name:"arch/tui-engine.md"};function o(d,e,r,h,c,l){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="tui-engine-the-full-screen-desktop-and-its-pages" tabindex="-1">TUI engine: the full-screen desktop and its pages <a class="header-anchor" href="#tui-engine-the-full-screen-desktop-and-its-pages" aria-label="Permalink to &quot;TUI engine: the full-screen desktop and its pages&quot;">​</a></h1><p>The TUI family is <code>ocos/services/tui/</code> - 25 source files, ~13.4k lines, the largest service family after font. It owns L1SVC category 20 with <strong>nine ops, all routed DIRECT</strong> (<code>out[0]=0</code>; the live console output IS the session, mirrored verbatim to the serial tee):</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_TUI</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui      (desktop)       */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_TEST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-test (selftests)     */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_HW</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">         3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-hw   [page]          */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_NET</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-net                  */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_SYSINFO</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-sysinfo [page]       */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_TIME</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">       6</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-time                 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_DRV</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        7</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-drv   [page]         */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_SYS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        8</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-sys   [page]         */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> L1SVC_TUI_EXT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        9</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* tui-ext                  */</span></span></code></pre></div><p>One desktop + eight pages: op 1 is the full-screen desktop; the other eight are the classic full-screen pages and their self-test surface (<code>tui-drv</code> keeps its v2.2.0 alias role - same body as <code>tui-hw</code>, own op number).</p><h2 id="why-every-op-runs-direct-the-kcap-constraint" tabindex="-1">Why every op runs DIRECT (the kcap constraint) <a class="header-anchor" href="#why-every-op-runs-direct-the-kcap-constraint" aria-label="Permalink to &quot;Why every op runs DIRECT (the kcap constraint)&quot;">​</a></h2><p>The L1SVC text surface normally works by capturing a command body&#39;s console output through <code>core_kcap_run_fn</code> - while a capture is active, the capture hook IS the console hook, and <strong>neither the framebuffer nor the serial tee sees the characters</strong> (<a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>). That is precisely wrong for a TUI: a full-screen session renders live, keystroke by keystroke, and its output must reach the screen <em>while the session runs</em>. Routing a TUI op captured would blank the screen for the whole session and then replay 30 KiB of ANSI soup into a buffer.</p><p>The verdict is recorded in source: <code>tui-test</code> was first routed through the capture, but its verdict block is ~4.4 KiB - the 4096-byte service result buffer truncated the final summary, so it went direct like v2.2.0. The same rule already governed <code>sshd</code> and <code>power sleep</code> (a captured multi-second park swallowed every console line printed meanwhile - found live during an OCIRE-supervised boot).</p><h2 id="the-file-inventory" tabindex="-1">The file inventory <a class="header-anchor" href="#the-file-inventory" aria-label="Permalink to &quot;The file inventory&quot;">​</a></h2><p>The family&#39;s <code>src/</code> directory, by role:</p><table tabindex="0"><thead><tr><th>Group</th><th>Files</th><th>Role</th></tr></thead><tbody><tr><td>dispatch</td><td><code>svc_tui_l1.c</code>, <code>svc_tui_cmd.{c,h}</code></td><td>cat-20 routing (all-direct) + command bodies</td></tr><tr><td>engine</td><td><code>core</code>, <code>win</code>, <code>panel</code>, <code>menu</code>, <code>text</code>, <code>form</code>, <code>input</code></td><td>the window stack, panels, menus, text widgets, forms, input pump</td></tr><tr><td>desktop</td><td><code>desktop</code>, <code>dt_apps</code>, <code>dt_cmdbr</code>, <code>dt_editor</code>, <code>dt_edtrm</code>, <code>dt_files</code>, <code>dt_proc</code></td><td>the full-screen desktop environment</td></tr><tr><td>classic pages</td><td><code>hw</code>, <code>net</code>, <code>sysinfo</code>, <code>time</code>, <code>sys</code>, <code>drv</code></td><td>the paged information screens</td></tr><tr><td>CJK</td><td><code>chinese</code>, <code>cn_hw</code>, <code>cn_net</code>, <code>cn_sysinfo</code></td><td>the Chinese renderings of the same pages</td></tr><tr><td>extension</td><td><code>ext</code>, <code>exec</code></td><td>the theme/hotkey registry and the app-execute bridge</td></tr><tr><td>tests</td><td><code>test</code></td><td>the <code>tui-test</code> battery</td></tr></tbody></table><p>The <code>cn_*</code> files exist because each classic page has a Chinese twin: <code>tui-hw</code> and <code>tui-hw</code>-equivalent CJK rendering share the data fetchers but render through <code>svc_font_render_cn</code> with bilingual labels (<a href="./chinese-layer.html">chinese-layer.md</a>).</p><h2 id="the-desktop-tui-op-1" tabindex="-1">The desktop (<code>tui</code> op 1) <a class="header-anchor" href="#the-desktop-tui-op-1" aria-label="Permalink to &quot;The desktop (\`tui\` op 1)&quot;">​</a></h2><p><code>svc_tui_desktop.c</code> + the <code>dt_*</code> files: a full-screen desktop environment with:</p><ul><li><strong>dt_apps</strong> - the application launcher (the L1 program registry rendered as launchable entries),</li><li><strong>dt_cmdbr</strong> - the command bar,</li><li><strong>dt_editor / dt_edtrm</strong> - the built-in editor and terminal,</li><li><strong>dt_files</strong> - the file manager (VFS-backed),</li><li><strong>dt_proc</strong> - the process viewer (the <code>SYS_PS</code> table).</li></ul><p>Rendering goes through the CJK-aware renderer (<code>svc_font_render_cn</code>) and the window/panel/menu/text/form/widget layer (<code>svc_tui_{win,panel, menu,text,form}.c</code>); input comes through the console input mux (PS/2 + serial CSI-decoded arrows; xterm SGR mouse reports pass through raw for the mouse decoder). The IME is the <em>system</em> IME engine (<code>svc_display_ime_engine.h</code>) - the same engine the editors use (<a href="./chinese-layer.html">chinese-layer.md</a>).</p><h2 id="the-classic-pages" tabindex="-1">The classic pages <a class="header-anchor" href="#the-classic-pages" aria-label="Permalink to &quot;The classic pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Content</th></tr></thead><tbody><tr><td><code>tui-hw</code> / <code>tui-drv</code> <code>[page]</code></td><td>hardware/driver inventory, paged - the PCIe cache, block devices, NICs, sound cards, USB tree</td></tr><tr><td><code>tui-net</code></td><td>network status - interfaces, ARP, routes, sockets, firewall</td></tr><tr><td><code>tui-sysinfo</code> <code>[page]</code></td><td>system info - version, uptime, memory, tasks</td></tr><tr><td><code>tui-time</code></td><td>clock sources - RTC/HPET/PM-timer/TSC status</td></tr><tr><td><code>tui-sys</code> <code>[page]</code></td><td>system management - health, klog tail, watchdog</td></tr><tr><td><code>tui-ext</code></td><td>the TUI extension surface demo (registered hotkeys/themes - <a href="./../l1/tui-ext.html">../l1/tui-ext.md</a>)</td></tr><tr><td><code>tui-test</code></td><td>the self-test battery (window manager, widget, input, render checks)</td></tr></tbody></table><h2 id="the-self-test-battery-tui-test-op-2" tabindex="-1">The self-test battery (<code>tui-test</code> op 2) <a class="header-anchor" href="#the-self-test-battery-tui-test-op-2" aria-label="Permalink to &quot;The self-test battery (\`tui-test\` op 2)&quot;">​</a></h2><p><code>tui-test</code> runs the engine&#39;s own acceptance suite live on screen: window create/destroy/z-order, panel and menu navigation, text widget rendering (including wide-cell CJK), form field editing, the input pump, dirty-rect repaint correctness, and the extension registry. Its verdict block is ~4.4 KiB - the historical fact that decided the family&#39;s all-direct routing (below). The E2E batteries (<code>tools/tui_g11c_e2e.py</code> and the tui acceptance transcripts) verify pages headlessly by grepping the serial mirror of exactly this output.</p><h2 id="input-and-output-plumbing" tabindex="-1">Input and output plumbing <a class="header-anchor" href="#input-and-output-plumbing" aria-label="Permalink to &quot;Input and output plumbing&quot;">​</a></h2><ul><li><strong>Keys</strong>: the console input mux merges the PS/2 queue and the COM1 serial bridge; the bridge&#39;s ANSI CSI decoder pre-decodes <code>ESC [ A/B/C/D</code> arrows and <code>ESC [ H/F</code> Home/End into OC_KEY_* codes so a serial terminal drives the TUI identically to the local keyboard (<a href="./interrupts.html">interrupts.md</a>).</li><li><strong>Mouse</strong>: xterm SGR reports (<code>ESC [ &lt; ... M/m</code>) pass through the CSI decoder raw, for the TUI&#39;s own mouse decoder; locally, pointer input comes from USB HID mice and the i2c-hid touchpad (<a href="./driver-model.html">driver-model.md</a>).</li><li><strong>Output</strong>: every page renders ANSI escape sequences into the console; the serial tee mirrors them verbatim - which is why the acceptance transcripts are greppable and why headless automation works at all.</li></ul><h2 id="init-and-extension-points" tabindex="-1">Init and extension points <a class="header-anchor" href="#init-and-extension-points" aria-label="Permalink to &quot;Init and extension points&quot;">​</a></h2><p>The family&#39;s <code>OC_SERVICE_DECL_L1</code> carries the one init slot among services with entry points: <code>tui_ext_init()</code> warms the builtin themes and hotkeys <strong>before the first op runs</strong> - the extension registry must exist before any page asks for a theme. Registered extensions (themes, hotkeys) survive across ops for the whole session.</p><p>The engine&#39;s own primitives (window stack, z-order, dirty-rect repaint, ANSI rendering) are internal to <code>svc_tui_{core,win,panel}.c</code>; the public extension surface for L1 apps is documented in <a href="./../l1/tui-ext.html">../l1/tui-ext.md</a>, and the user guide is <a href="./../manual/tui-guide.html">../manual/tui-guide.md</a>.</p><h2 id="relationship-to-the-rest" tabindex="-1">Relationship to the rest <a class="header-anchor" href="#relationship-to-the-rest" aria-label="Permalink to &quot;Relationship to the rest&quot;">​</a></h2><ul><li><strong>Font/encoding</strong>: every page renders through the same CJK pipeline as the console - 16x16 GB2312 glyphs for wide cells, 8x16 ASCII otherwise (<a href="./chinese-layer.html">chinese-layer.md</a>).</li><li><strong>Data sources</strong>: pages are renderers over the same kernel tables the CLI reads - <code>net_get_stats()</code>, the socket table, <code>SYS_PS</code>, PMM/heap stats, klog replay, watchdog slots (<a href="./network-stack.html">network-stack.md</a>, <a href="./scheduler.html">scheduler.md</a>, <a href="./../internals/klog.html">../internals/klog.md</a>).</li><li><strong>Serial mirroring</strong>: because the ops are direct, the serial tee carries the full ANSI session - which is exactly how the E2E batteries (<code>tools/tui_g11c_e2e.py</code>, the tui acceptance transcripts) verify pages headlessly.</li><li><strong>The config knobs are gone</strong>: <code>CONFIG_TUI</code>/<code>CONFIG_CHINESE</code> were deleted with the old TUI plane - the CJK pipeline and the TUI are unconditionally compiled in.</li></ul>`,26)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
